// Author: MiYu. Source worker/mine commands, occupancy, carried gold, direct mining and resource lifetime consumers.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>
#include <algorithm>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_harvest_tests <data-root> <generated-map> [depot-route|tree-partial|tree-invu|tree-invulnerable|stunned|mine-paused]");if(argc==4 && std::wstring(argv[3])!=L"depot-route" && std::wstring(argv[3])!=L"depot-stuck" && std::wstring(argv[3])!=L"tree-partial" && std::wstring(argv[3])!=L"tree-invu" && std::wstring(argv[3])!=L"tree-invulnerable" && std::wstring(argv[3])!=L"stunned" && std::wstring(argv[3])!=L"mine-paused")throw std::runtime_error("Unknown harvest check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto check=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};float x=std::bit_cast<float>(vm.invoke("GetStartLocationX",std::array{vm.integer(0)}).bits),y=std::bit_cast<float>(vm.invoke("GetStartLocationY",std::array{vm.integer(0)}).bits);auto spawn=[&](const char* type,unsigned owner,float dx){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(type))),vm.real(real(x+dx)),vm.real(real(y)),vm.real(real(270))});};auto resource=[&](jass::Value mine,int amount){vm.invoke("SetResourceAmount",std::array{mine,vm.integer(amount)});};auto state=[&](unsigned owner,unsigned key){auto& values=session.config().players[owner].states;auto it=values.find(key);return it==values.end()?0:it->second;};
        if(argc==4 && std::wstring(argv[3])==L"mine-paused"){auto mine=spawn("ngol",15,0),worker=spawn("hpea",0,32);resource(mine,100);check(session.harvest(worker.bits,mine.bits),"Paused mine setup rejected");session.advance(.03125);auto u=session.units().at(worker.bits);check(u->gather.phase==GatherOrder::Phase::Mine,"Worker did not enter mine");double remaining=u->gather.due-session.simulationTime();vm.invoke("PauseUnit",std::array{mine,vm.boolean(true)});session.advance(2);check(u->gather.phase==GatherOrder::Phase::Mine && !u->carriedGold && session.units().at(mine.bits)->resources==100 && std::abs((u->gather.due-session.simulationTime())-remaining)<.001,"Paused mine continued gathering or lost its remaining interval");vm.invoke("PauseUnit",std::array{mine,vm.boolean(false)});session.advance(1.1);check(u->carriedGold==10 && session.units().at(mine.bits)->resources==90,"Mine did not resume gathering after pause");std::cout<<"PASS paused_mine_gather_resume\n";return 0;}
        if(argc==4 && std::wstring(argv[3])==L"stunned"){auto worker=spawn("hpea",0,0);auto u=session.units().at(worker.bits);auto tree=vm.invoke("CreateDestructable",std::array{vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("LTlt"))),vm.real(real(x+64)),vm.real(real(y)),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});auto treeState=session.destructables().at(tree.bits);check(session.targetOrder(worker.bits,tree.bits,852018),"Stunned harvest setup rejected");session.advance(.03125);check(u->gather.phase==GatherOrder::Phase::Chop,"Harvest did not enter chop phase");auto stunId=ObjectData::code("BPSE");UnitBuff stun;stun.id=stunId;stun.target=worker.bits;stun.kind=BuffKind::Stun;stun.persistent=true;u->buffs[stunId]=stun;float treeLife=treeState->life;auto remaining=u->gather.due-session.simulationTime();session.advance(2);check(treeState->life==treeLife && !u->carriedLumber && u->gather.phase==GatherOrder::Phase::Chop && std::abs((u->gather.due-session.simulationTime())-remaining)<.001,"Stunned worker continued chopping or lost its remaining interval");u->buffs.erase(stunId);session.advance(2);check(treeState->life<treeLife,"Worker did not resume chopping after stun");session.stopUnit(worker.bits);u->carriedLumber=0;u->carriedGold=10;auto depot=spawn("htow",0,96);check(session.returnResources(worker.bits,depot.bits),"Stunned deposit setup rejected");u->buffs[stunId]=stun;int before=state(0,1);session.advance(.25);check(u->carriedGold==10 && state(0,1)==before,"Stunned worker deposited gold");u->buffs.erase(stunId);session.advance(1);check(!u->carriedGold && state(0,1)==before+10,"Worker did not deposit after stun");std::cout<<"PASS stunned_harvest_and_deposit_resume\n";return 0;}
        if(argc==4 && std::wstring(argv[3])==L"depot-stuck"){auto depot=spawn("htow",0,0),worker=spawn("hpea",0,500);auto unit=session.units().at(worker.bits),hall=session.units().at(depot.bits);unit->carriedGold=10;check(session.returnResources(worker.bits,depot.bits),"Cannot start resource return");auto goal=unit->route.back();unit->moveSpeed=real(0);unit->routeWatch=true;unit->routeWatchSince=session.simulationTime()-9;unit->routeWatchPosition={unit->x,unit->y};unit->routeWatchGoal=unit->route[unit->waypoint];unit->gather.repath=0;session.advance(.03125);check(!unit->route.empty() && (unit->route.back().x.bits()!=goal.x.bits() || unit->route.back().y.bits()!=goal.y.bits()),"Stuck return did not choose another depot entrance");check(unit->carriedGold==10 && unit->gather.phase==GatherOrder::Phase::Return && unit->gather.depot==depot.bits && unit->currentOrder==852020,"Entrance retry changed resource or order state");auto end=unit->route.back();check(std::hypot(std::bit_cast<float>(end.x.bits())-std::bit_cast<float>(hall->x.bits()),std::bit_cast<float>(end.y.bits())-std::bit_cast<float>(hall->y.bits()))<=hall->collision+unit->collision+32.01f,"Alternative entrance cannot deliver resources");std::cout<<"PASS stalled_depot_entrance_retry\n";return 0;}
        if(argc==4 && std::wstring(argv[3])!=L"depot-route"){bool allowed=std::wstring(argv[3])!=L"tree-partial";auto worker=spawn("hpea",0,0);auto tree=vm.invoke("CreateDestructable",std::array{vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("LTlt"))),vm.real(real(x+64)),vm.real(real(y)),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});vm.invoke("SetDestructableInvulnerable",std::array{tree,vm.boolean(true)});check(session.targetOrder(worker.bits,tree.bits,852018)==allowed,"Invulnerable tree target list was not matched by complete token");if(!allowed){vm.invoke("SetDestructableInvulnerable",std::array{tree,vm.boolean(false)});check(session.targetOrder(worker.bits,tree.bits,852018),"Vulnerable tree rejected");vm.invoke("SetDestructableInvulnerable",std::array{tree,vm.boolean(true)});session.advance(.03125);check(session.units().at(worker.bits)->gather.phase==GatherOrder::Phase::None,"Harvest continued after tree became invulnerable");}else{session.advance(.03125);check(session.units().at(worker.bits)->gather.phase!=GatherOrder::Phase::None,"Allowed invulnerable tree harvest was cancelled");auto next=vm.invoke("CreateDestructable",std::array{vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("LTlt"))),vm.real(real(x+64)),vm.real(real(y)),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});vm.invoke("SetDestructableInvulnerable",std::array{next,vm.boolean(true)});vm.invoke("KillDestructable",std::array{tree});session.advance(.3);check(session.units().at(worker.bits)->gather.tree==next.bits,"Harvest did not select an allowed invulnerable replacement tree");}std::cout<<"PASS harvest_tree_target_tokens\n";return 0;}
        if(argc==4){auto depot=spawn("htow",0,0),worker=spawn("hpea",0,500);auto unit=session.units().at(worker.bits),hall=session.units().at(depot.bits);unit->carriedGold=10;for(int dx=176;dx<=272;dx+=32)for(int dy=-64;dy<=64;dy+=32)session.world()->terrainPathable({real(x+dx),real(y+dy)},1,false);check(session.returnResources(worker.bits,depot.bits),"Blocked depot side rejected every entrance");auto goal=unit->route.back();check(std::abs(std::bit_cast<float>(goal.y.bits())-std::bit_cast<float>(hall->y.bits()))>16,"Depot path did not select another entrance");session.advance(20);check(unit->carriedGold==0 && state(0,1)==10,"Worker did not deliver through alternate entrance");std::cout<<"PASS depot_alternate_entrance\n";return 0;}
        for(unsigned owner=0;owner<3;++owner)for(unsigned other=0;other<3;++other)if(owner!=other)vm.invoke("SetPlayerAlliance",std::array{vm.handle("player",0x100000+owner),vm.handle("player",0x100000+other),vm.handle("alliancetype",0),vm.boolean(true)});auto mine=spawn("ngol",15,0),worker=spawn("hpea",0,32);spawn("htow",0,64);resource(mine,25);check(session.harvest(worker.bits,mine.bits),"Normal mine command rejected");session.advance(1.03125);check(session.units().at(worker.bits)->carriedGold==10 && !session.units().at(worker.bits)->gather.inside && state(0,1)==0,"Mine did not produce carried gold before deposit");check(session.stopUnit(worker.bits) && session.units().at(worker.bits)->carriedGold==10,"Stop discarded carried gold");auto buttons=session.commands(worker.bits,0);check(std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.action==CommandAction::ReturnResources;}),"Carried gold did not change command button");check(vm.invoke("IssueImmediateOrder",std::array{worker,vm.string("returnresources")}).bits!=0,"Return command rejected");session.advance(.03125);check(state(0,1)==10 && state(0,15)==10 && session.units().at(worker.bits)->carriedGold==0,"Deposit did not update current/cumulative resource states");check(session.stopUnit(worker.bits),"Stop before lumber return failed");session.units().at(worker.bits)->carriedLumber=20;check(vm.invoke("IssueImmediateOrder",std::array{worker,vm.string("returnresources")}).bits!=0,"Lumber return command rejected");session.advance(.03125);auto score=[&](int kind){return std::bit_cast<std::int32_t>(vm.invoke("GetPlayerScore",std::array{vm.handle("player",0x100000),vm.handle("playerscore",kind)}).bits);};check(score(11)==10 && score(16)==20 && score(23)==30,"Resource total did not consume deposited gold and lumber");check(score(25)==0 && vm.invoke("GetPlayerScore",std::array{vm.handle("player",0),vm.handle("playerscore",23)}).bits==0,"Invalid score or player did not return zero");check(session.harvest(worker.bits,mine.bits),"Repeated harvest rejected");session.advance(3);check(session.units().at(mine.bits)->resources==0 && std::bit_cast<float>(session.units().at(mine.bits)->life.bits())==0 && state(0,1)==25,"Finite mine depletion or final partial load differs");
        auto haunted=spawn("ugol",1,0),acolyte=spawn("uaco",1,32);resource(haunted,30);check(session.harvest(acolyte.bits,haunted.bits),"Acolyte mine command rejected");session.advance(1.03125);check(state(1,1)==2 && session.units().at(acolyte.bits)->carriedGold==0 && !session.units().at(acolyte.bits)->gather.inside,"Acolyte mine did not credit direct proportional gold");check(!session.harvest(worker.bits,haunted.bits),"Wrong worker accepted for haunted mine");
        auto entangled=spawn("egol",2,0),wisp=spawn("ewsp",2,32);resource(entangled,30);check(session.harvest(wisp.bits,entangled.bits),"Wisp mine command rejected");session.advance(.03125);check(session.units().at(wisp.bits)->gather.inside && vm.invoke("IsUnitHidden",std::array{wisp}).bits!=0,"Inside wisp still exposed as visible");vm.invoke("PauseUnit",std::array{wisp,vm.boolean(true)});session.advance(2);check(state(2,1)==0,"Paused mining advanced");vm.invoke("PauseUnit",std::array{wisp,vm.boolean(false)});session.advance(1);check(state(2,1)==2,"Resumed wisp mine did not credit gold");vm.invoke("RemoveUnit",std::array{entangled});session.advance(.03125);check(!session.units().at(wisp.bits)->gather.inside && session.units().at(wisp.bits)->gather.phase==GatherOrder::Phase::None,"Mine removal retained hidden worker");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS harvest consumers: source mines, carried/deposited gold, commands, pause, depletion and removal\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
